function setup() {
  cnv = createCanvas(600, 600);
  noStroke();
  peeps = [];
  r = max(width, height) / 3;
  n = random(1000, 3000);
  describe("a constellation on a sphere that twists slowly into a torus. lines are light on a dark slate-teal background. the size and density is randomized")
  thresh = r / 10 + random(0, r / 10);
  for (let i = 0; i < n; i++) {
    a = acos(random(-1, 1));
    b = random(0, 2 * PI);
    x = r * Math.sin(a) * Math.cos(b);
    y = r * Math.sin(a) * Math.sin(b);
    z = r * Math.cos(a);
    peeps.push(new Peep(a, b, x, y, z));
  }

  for (let i = 0; i < peeps.length; i++) {
    cnt = 0;
    cnt2 = 0;
    let _wG_1 = 0; while ((cnt < 1) && ++_wG_1 < 20000) {
