      }
      if (cnt2 > peeps.length * 2) {
        cnt = 1;
        peeps[i].n2 = i;
      }
    }
    cnt = 0;
    cnt2 = 0;
    let _wG_3 = 0; while ((cnt < 1) && ++_wG_3 < 20000) {
      int1 = int(random(0, peeps.length));

      dx = peeps[int1].x - peeps[i].x;
      dy = peeps[int1].y - peeps[i].y;
      dz = peeps[int1].z - peeps[i].z;
