    cnt2 = 0;
    let _wG_4 = 0; while ((cnt < 1) && ++_wG_4 < 20000) {
      int1 = int(random(0, peeps.length));

      dx = peeps[int1].x - peeps[i].x;
      dy = peeps[int1].y - peeps[i].y;
